        case Z_T4706_TAG_0:   whence = SEEK_SET; break;
        case Z_T4706_TAG_1: whence = SEEK_CUR; break;
        case Z_T4706_TAG_2:     whence = SEEK_END; break;
        default:                       whence = SEEK_SET; break;
