#include <mach-o/dyld.h>
#endif
static z_t836_t z_os_exePath(void);
static z_t836_t z_os_exePath(void) {
    z_t836_t out = {0};
#if defined(_WIN32)
    /* the buffer doubles until the name fits: a long path is not cut short */
    DWORD cap = 512;
    char* path = NULL;
    for (;;) {
        wchar_t* w = (wchar_t*)z_xmalloc((size_t)cap * sizeof(wchar_t));
        DWORD got = GetModuleFileNameW(NULL, w, cap);
        if (got == 0) {
            free(w);
            break;
        }
        if (got < cap) {
            path = z_win_utf8(w, (int)got, NULL);
            free(w);
            break;
        }
        free(w);
        cap *= 2;
    }
    if (path == NULL) {
        z_t834_t* boxed = (z_t834_t*)z_xmalloc(sizeof(z_t834_t));
        *boxed = z_io_os_error((int)GetLastError());
        out.tag = Z_T836_TAG_0;
        out.data = boxed;
        return out;
    }
    z_t63_t* sb = (z_t63_t*)z_xmalloc(sizeof(z_t63_t));
    *sb = z_t63_new(path);
    free(path);
    out.tag = Z_T836_TAG_1;
    out.data = sb;
    return out;
#else
    char buf[4096];
#if defined(__APPLE__)
    uint32_t bufsize = (uint32_t)sizeof(buf);
    if (_NSGetExecutablePath(buf, &bufsize) != 0) {
        z_t834_t* boxed = (z_t834_t*)z_xmalloc(sizeof(z_t834_t));
        z_t834_t e = {0};
        e.tag = Z_T834_TAG_10;
        z_t63_t* sp = (z_t63_t*)z_xmalloc(sizeof(z_t63_t));
        *sp = z_t63_new("the executable's path is longer than 4095 bytes");
        e.data = sp;
        *boxed = e;
        out.tag = Z_T836_TAG_0;
        out.data = boxed;
        return out;
    }
#else
    ssize_t len = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
    if (len < 0) {
        int e = errno;
        z_t834_t* boxed = (z_t834_t*)z_xmalloc(sizeof(z_t834_t));
        *boxed = z_io_os_error(e);
        out.tag = Z_T836_TAG_0;
        out.data = boxed;
        return out;
    }
    buf[len] = '\0';
#endif
    z_t63_t* boxed = (z_t63_t*)z_xmalloc(sizeof(z_t63_t));
    *boxed = z_t63_new(buf);
    out.tag = Z_T836_TAG_1;
    out.data = boxed;
    return out;
#endif
}


